// ?Create@AptBoolean@@SAPAV1@_N@Z
// AptBoolean::Create allocates or reuses the 12-byte pooled boolean value.

class AptValue;
class AptBoolean;

struct AptBooleanRegistry
{
	int m_capacity;
	int m_count;
	AptValue **m_entries;

	__forceinline void add(AptValue *value);
};

typedef void *(__cdecl *AptAllocate)(unsigned int);

inline void *operator new(unsigned int, void *place)
{
	return place;
}

#define g_aptBooleanFreeList (*(AptBoolean **)0x013387D4)
#define g_aptBooleanRegistry (*(AptBooleanRegistry **)0x01337810)
#define g_aptAllocate (*(AptAllocate *)0x01337828)

class __declspec(novtable) AptValue
{
public:
	virtual void Release();

	__forceinline AptValue(unsigned int kind);

	unsigned int m_flags;
};

__forceinline void AptBooleanRegistry::add(AptValue *value)
{
	int index = m_count;
	int capacity = m_capacity;
	if (index >= capacity)
	{
		value->m_flags &= ~0x40000000;
		return;
	}
	m_entries[index] = value;
	++m_count;
}

__forceinline AptValue::AptValue(unsigned int kind)
{
	unsigned int flags = m_flags;
	flags &= 0xf0008000 | kind;
	flags |= 0x40008000 | kind;
	*(unsigned int *)this = 0x01135d68;
	m_flags = flags;
	g_aptBooleanRegistry->add(this);
}

class __declspec(novtable) AptBoolean : public AptValue
{
public:
	virtual ~AptBoolean();

	static AptBoolean *Create(bool value);
	__forceinline AptBoolean(bool value) : AptValue(5)
	{
		*(unsigned int *)this = 0x011360a8;
		m_value = value;
	}

	union
	{
		AptBoolean *m_next;
		unsigned char m_value;
	};
};

AptBoolean *AptBoolean::Create(bool value)
{
	AptBoolean *object = g_aptBooleanFreeList;
	AptBoolean *result;
	if (object != 0)
	{
		AptBoolean *next = object->m_next;
		AptBooleanRegistry *registry = g_aptBooleanRegistry;
		g_aptBooleanFreeList = next;
		registry->add(object);
		object->m_value = value;
		result = object;
	}
	else
	{
		void *raw = g_aptAllocate(12);
		if (raw != 0)
			result = new (raw) AptBoolean(value);
		else
			result = 0;
	}
	return result;
}
